            const httpError = toHttpError(cause);
            await writeEvent({
              type: "error",
              code: "INTERNAL_ERROR",
              message: httpError?.message ?? (cause instanceof Error ? cause.message : "Failed to dispatch execution action"),
            });
            await writeEvent({ type: "done" });
          } finally {
            await writeQueue;
            stopHeartbeat();
          }
        });
